                check(value, target, path)
            except (KeyError, TypeError):
                pass
        types = rule.get('type')
        if types:
            types = [types] if isinstance(types, str) else types
            if not any(_type(value, t) for t in types):
                errors.append(f"{path}: Expected {', '.join(types)}")
                return
        if 'enum' in rule and value not in rule['enum']:
            errors.append(f"{path}: Must be one of the allowed values")
        if 'const' in rule and value != rule['const']:
            errors.append(f"{path}: Must be equal to constant")
        if isinstance(value, (int, float)) and not isinstance(value, bool) and 'type' not in rule:
            # Numeric schema keywords apply without a declared type.
            pass
        if isinstance(value, dict):
            for key in rule.get('required', []):
                if key not in value:
                    errors.append(f"{path}: {key}: Required property is missing")
            props = rule.get('properties', {})
            patterns = rule.get('patternProperties', {})
            for key, val in value.items():
                subpath = f"{path}.{key}" if path else key
                matched = False
                if key in props:
                    check(val, props[key], subpath)
                    matched = True
                for pat, subrule in patterns.items():
                    try:
                        if re.search(pat, key):
                            check(val, subrule, subpath)
                            matched = True
                    except re.error:
                        pass
                if not matched and rule.get('additionalProperties') is False:
                    errors.append(f"{subpath}: Additional property is not allowed")
                elif not matched and isinstance(rule.get('additionalProperties'), dict):
                    check(val, rule['additionalProperties'], subpath)
            if 'minProperties' in rule and len(value) < rule['minProperties']:
                errors.append(f"{path}: Must have at least {rule['minProperties']} properties")
            if 'maxProperties' in rule and len(value) > rule['maxProperties']:
                errors.append(f"{path}: Must have at most {rule['maxProperties']} properties")
        elif isinstance(value, list):
            if 'minItems' in rule and len(value) < rule['minItems']:
                errors.append(f"{path}: Must have at least {rule['minItems']} items")
            if 'maxItems' in rule and len(value) > rule['maxItems']:
                errors.append(f"{path}: Must have at most {rule['maxItems']} items")
            if rule.get('uniqueItems'):
                for i, item in enumerate(value):
                    if item in value[:i]:
                        errors.append(f"{path}[{i}]: Items must be unique")
            items = rule.get('items')
            if isinstance(items, dict):
                for i, item in enumerate(value):
                    check(item, items, f"{path}[{i}]")
            elif isinstance(items, list):
                for i, (item, subrule) in enumerate(zip(value, items)):
                    check(item, subrule, f"{path}[{i}]")
        if isinstance(value, str):
            if 'minLength' in rule and len(value) < rule['minLength']:
                errors.append(f"{path}: String length must be greater than or equal to {rule['minLength']}")
            if 'maxLength' in rule and len(value) > rule['maxLength']:
                errors.append(f"{path}: String length must be less than or equal to {rule['maxLength']}")
            if 'pattern' in rule:
                try:
                    if not re.search(rule['pattern'], value):
                        errors.append(f"{path}: Must match pattern " + rule['pattern'])
                except re.error:
                    pass
            if 'format' in rule:
                if rule['format'] == 'email' and not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', value):
                    errors.append(f"{path}: Must be a valid email address")
                elif rule['format'] == 'uri' and not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:', value):
                    errors.append(f"{path}: Must be a valid URI")
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            for key, op, words in [('minimum', lambda a,b:a<b, ('greater than or equal to',)), ('maximum', lambda a,b:a>b, ('less than or equal to',))]:
                if key in rule and op(value, rule[key]):
                    errors.append(f"{path}: Must be {words[0]} {rule[key]}")
            if 'exclusiveMinimum' in rule and value <= rule['exclusiveMinimum']:
                errors.append(f"{path}: Must be greater than {rule['exclusiveMinimum']}")
            if 'exclusiveMaximum' in rule and value >= rule['exclusiveMaximum']:
                errors.append(f"{path}: Must be less than {rule['exclusiveMaximum']}")
            if 'multipleOf' in rule and rule['multipleOf'] and value % rule['multipleOf'] != 0:
