        if 'oneOf' in rule and sum(not _validate(value, s) for s in rule['oneOf']) != 1:
            errors.append(f"{path}: Must match exactly one schema")
        if 'not' in rule and not _validate(value, rule['not']):
            errors.append(f"{path}: Must not match schema")

    check(instance, schema, '')
    return errors


def _type(value, kind):
    return {'object': lambda: isinstance(value, dict), 'array': lambda: isinstance(value, list),
            'string': lambda: isinstance(value, str), 'number': lambda: isinstance(value, (int,float)) and not isinstance(value,bool),
            'integer': lambda: isinstance(value,int) and not isinstance(value,bool), 'boolean': lambda: isinstance(value,bool),
            'null': lambda: value is None}.get(kind, lambda: True)()


def _validate(value, schema):
    return not validate_schema(value, schema)
